		clusterLabels: {"0": {"label": "Urban Mobility & Spatial Segregation", "description": "Coarser grouping of mobility-and-space work: GPS traces, mobile-device records, and gravity models study urban segregation, accessibility barriers, displacement, and hybrid-work travel patterns."}, "1": {"label": "Race & Gender Bias In Media", "description": "Coarser grouping on representational bias: name-based classifiers and generative-AI audits quantify racial and gender stereotypes across films, fiction, product pricing, and lending."}, "2": {"label": "Cultural Evolution & Creative Networks", "description": "Coarser grouping of cultural-dynamics work: collaboration networks and popularity-feedback experiments model how social learning shapes innovation across art, perfume, K-pop, and creator economies."}, "3": {"label": "Text-As-Data For Politics & Discourse", "description": "Broad grouping using LLM annotation, ASR validation, and NLP pipelines to measure political polarization, election toxicity, news bias, civic-participation transcripts, and reliability of automated content analysis."}, "4": {"label": "Online Diffusion, Belief & Contagion", "description": "Broad grouping of platform-trace studies on X, TikTok, Reddit, and Threads covering conspiracy and moral contagion, protest mobilization, belief dynamics, influencer amplification, and feed-algorithm misalignment."}, "5": {"label": "LLMs As Human Behavior Proxies", "description": "Coarser grouping validating LLMs as synthetic respondents and reasoning agents, auditing companion chatbots and recommenders, and using chain-of-thought traces as social-science data."}, "6": {"label": "Labor Markets & Career Trajectories", "description": "Coarser grouping on careers: mobility-grounded embeddings and administrative records study occupational skills, AI job exposure, remote-work outcomes, faculty paths, and student retention."}, "7": {"label": "Science Of Science & Innovation", "description": "Coarser grouping using publication, patent, grant, and peer-review datasets to quantify innovation search, interdisciplinarity, translational impact, and pivot penalties in scientific careers."}, "8": {"label": "LLMs In Scholarly Knowledge Production", "description": "Coarser grouping measuring LLM-assisted writing adoption, Wikipedia and AI-search knowledge pipelines, and gender, geographic, and access biases in peer review and scientific recognition."}},
