		clusterLabels: {"0": {"label": "Mobility, Space & Population-Scale Data", "description": "Broad grouping of spatial and mobility research using large-scale trajectory, administrative, and geolocation data to study urban movement, segregation, displacement, and the predictability of life-course outcomes."}, "1": {"label": "Platforms, Politics & Collective Beliefs", "description": "Broad grouping spanning recommender-feed audits, information diffusion, content moderation, polarization, news media bias, protest mobilization, and belief-network dynamics across social platforms."}, "2": {"label": "Science, Innovation & AI In Institutions", "description": "Broad grouping of science-of-science, innovation search, and recognition-inequality studies together with the adoption and governance of generative AI in writing, coding, education, and academic careers."}, "3": {"label": "LLMs As Instruments & Objects Of Study", "description": "Broad grouping treating LLMs both as measurement tools for annotation, fact-checking, and survey simulation and as objects of study through probing of their reasoning, empathy, narratives, and biases."}},
		clusterLayerLabels: [{"0": {"label": "Bias & Stereotypes In Representation", "description": "Measuring racial and gender bias and stereotyping in product pricing, algorithmic lending, capital trials, and film/fiction representation using name-based classifiers, computer vision, and generative-image audits."}, "1": {"label": "Urban Mobility & Population-Scale Prediction", "description": "Human mobility and life-course outcomes studied with origin-destination traces, mobility neural embeddings, gravity/deterrence models, and nationwide administrative registers, covering commuting, segregation, disaster displacement, and limits of prediction."}, "2": {"label": "LLMs As Measurement & Annotation Tools", "description": "Validating and deploying LLMs for text annotation, content analysis, fact-checking, and synthetic survey simulation, probing their reasoning, biases, and reliability against human ground truth."}, "3": {"label": "Generative AI Adoption & Cultural Evolution", "description": "Tracking the spread and governance of LLM-assisted writing and coding in education, petitions, and science, plus network models of artistic and cultural evolution via WikiArt and Wikipedia data."}, "4": {"label": "Platform Algorithms & Content Moderation", "description": "How recommender feeds, bots, and moderation shape virality, contagion, and creator economies across TikTok, Reddit, YouTube, and X, using audits, hypergraph diffusion models, and platform-trace data."}, "5": {"label": "Belief Networks & Opinion Dynamics", "description": "Reconstructing individual and cross-national belief systems from surveys and news comments as weighted networks, and testing opinion-dynamics mechanisms like anticonformity and belief fields in group experiments."}, "6": {"label": "Political Polarization & News Media Bias", "description": "Quantifying partisan polarization, feed-algorithm bias, and slanted news coverage of crime, elections, and out-parties using audits, masked-language models, and large headline and transcript corpora."}, "7": {"label": "Online Activism, Protest & Harmful Speech", "description": "Network and narrative analysis of hashtag activism, protest mobilization, cyberbullying, and cross-border harmful speech across Facebook, TikTok, Threads, Instagram, and YouTube during crises and movements."}, "8": {"label": "Science Of Science & Innovation", "description": "Large-scale bibliometric and patent analysis of innovation search, interdisciplinarity, data reuse, execution effort, translation, and funding impact in the science-of-science tradition."}, "9": {"label": "Recognition Inequality In Academia", "description": "Causal and survey evidence of gender, geographic, and institutional bias in peer review, self-promotion, citation, and paywalled-access, revealing structural asymmetries in scholarly recognition."}}, {"0": {"label": "Mobility, Space & Population-Scale Data", "description": "Broad grouping of spatial and mobility research using large-scale trajectory, administrative, and geolocation data to study urban movement, segregation, displacement, and the predictability of life-course outcomes."}, "1": {"label": "Platforms, Politics & Collective Beliefs", "description": "Broad grouping spanning recommender-feed audits, information diffusion, content moderation, polarization, news media bias, protest mobilization, and belief-network dynamics across social platforms."}, "2": {"label": "Science, Innovation & AI In Institutions", "description": "Broad grouping of science-of-science, innovation search, and recognition-inequality studies together with the adoption and governance of generative AI in writing, coding, education, and academic careers."}, "3": {"label": "LLMs As Instruments & Objects Of Study", "description": "Broad grouping treating LLMs both as measurement tools for annotation, fact-checking, and survey simulation and as objects of study through probing of their reasoning, empathy, narratives, and biases."}}],
