		clusterLabels: {"0": {"label": "Spatial, Mobility & Belief Systems", "description": "Broad grouping of urban mobility and segregation, social-influence and belief-network studies, and homophily research, tying geospatial and population-scale behavioral data to collective belief and network formation."}, "1": {"label": "Science, Inequality & AI In Research", "description": "Broad grouping of science-of-science, innovation, and scholarly inequality themes, spanning peer review, retractions, LLM-driven scientific production, and gender and racial biases in recognition and representation."}, "2": {"label": "LLMs For Text Analysis & Simulation", "description": "Broad grouping of LLM-as-instrument work, covering synthetic survey validation, content annotation, persuasion modeling, fact-checking, empathy taxonomies, and interpretable social simulation from language models."}, "3": {"label": "Social Media Diffusion & Harms", "description": "Broad grouping of platform-dynamics research on narrative and conspiracy diffusion, recommendation algorithms, online hate and stigma, and content-moderation effects across major social platforms."}, "4": {"label": "Political Communication & Polarization", "description": "Broad grouping of political-media studies measuring polarization, media bias, election toxicity, and news framing across social feeds, broadcast transcripts, and audio-as-data."}},
		clusterLayerLabels: [{"0": {"label": "GenAI Governance In Higher Education", "description": "How universities respond to generative AI through syllabus policies, institutional governance audits, and instructor-governed tools, using LLM-annotation pipelines over syllabi, discussion-forum posts, and policy documents."}, "1": {"label": "Urban Mobility & Spatial Segregation", "description": "Cities as data: mobility traces, POI composition, and geospatial data used to study segregation, accessibility, displacement, and mobility deterrence, with attention to correcting biases in GPS and simulated mobility datasets."}, "2": {"label": "Social Influence, Belief & Homophily", "description": "Opinion dynamics, collective intelligence, and belief-network experiments examining how social influence, anticonformity, and homophily (including facial similarity and prosociality) shape polarization and tie formation."}, "3": {"label": "Labor Markets & Career Trajectories", "description": "Occupational mobility, skill compatibility, and career embeddings applied to green-job transitions, faculty pipelines, and student retention, mapping how skills and preferences structure job and educational trajectories."}, "4": {"label": "Cultural Evolution & Creative Innovation", "description": "Social-learning dynamics of art, perfume, and coding practices, using large artwork and cultural corpora plus generative simulations to study cumulative culture, popularity feedback, and AI-driven convergence in creative production."}, "5": {"label": "LLMs As Social-Science Instruments", "description": "Validating and probing LLMs as annotators, synthetic survey respondents, persuaders, and fact-checkers, covering reliability diagnostics, bias mechanisms, moral reasoning, and chain-of-thought reasoning treated as social-science data."}, "6": {"label": "AI Research Ethics & Transparency", "description": "Ethical and methodological scrutiny of AI in research and platforms, spanning agentic evidence synthesis, survey-research disclosure standards, challenge-study ethics, and audits of AI overviews and petition tools."}, "7": {"label": "Science Of Science & Innovation", "description": "Metascience of innovation, peer review, and productivity, using publication, patent, funding, and data-reuse records to quantify pivot penalties, interdisciplinarity, translational impact, and reviewer diversity effects."}, "8": {"label": "Gender & Racial Representation In Media", "description": "Measuring racial and gender stereotypes across Hollywood films, fiction archetypes, product pricing, lending, and AI-generated faces, using large media corpora and character-space embeddings to track visibility and portrayal biases."}, "9": {"label": "Gender Gaps In Scholarly Recognition", "description": "Inequality in academic visibility and recognition, examining gender gaps in Wikipedia notability, self-promotion, and AI-mediated citation, plus clickbait perceptions and AI's dual role in amplifying scientific inequality."}, "10": {"label": "Platform Dynamics & Online Harms", "description": "Diffusion of narratives, conspiracy theories, hate speech, and stigma across Reddit, X, TikTok, and YouTube, studying recommendation algorithms, content moderation, banned-community growth, and cross-border harmful speech."}, "11": {"label": "Political Polarization & News Media", "description": "Partisan polarization, media bias, and news framing measured across social feeds, cable and broadcast transcripts, and audio, covering copaganda, out-party coverage, false polarization, and algorithmic feed audits before elections."}}, {"0": {"label": "Spatial, Mobility & Belief Systems", "description": "Broad grouping of urban mobility and segregation, social-influence and belief-network studies, and homophily research, tying geospatial and population-scale behavioral data to collective belief and network formation."}, "1": {"label": "Science, Inequality & AI In Research", "description": "Broad grouping of science-of-science, innovation, and scholarly inequality themes, spanning peer review, retractions, LLM-driven scientific production, and gender and racial biases in recognition and representation."}, "2": {"label": "LLMs For Text Analysis & Simulation", "description": "Broad grouping of LLM-as-instrument work, covering synthetic survey validation, content annotation, persuasion modeling, fact-checking, empathy taxonomies, and interpretable social simulation from language models."}, "3": {"label": "Social Media Diffusion & Harms", "description": "Broad grouping of platform-dynamics research on narrative and conspiracy diffusion, recommendation algorithms, online hate and stigma, and content-moderation effects across major social platforms."}, "4": {"label": "Political Communication & Polarization", "description": "Broad grouping of political-media studies measuring polarization, media bias, election toxicity, and news framing across social feeds, broadcast transcripts, and audio-as-data."}}],
