		clusterLabels: {"0": {"label": "Spatial Mobility & Urban Segregation", "description": "Broad grouping of spatial computational social science on mobility, experienced segregation, accessibility, displacement, and cultural consumption using POI, geotagged, GPS, and higher-order network data."}, "1": {"label": "Science, Careers, Culture & Education", "description": "Broad grouping spanning science-of-science and innovation, academic bias and careers, labor mobility, media and gender stereotypes, and generative AI in education, largely via bibliometric, resume, and LLM-annotation methods."}, "2": {"label": "LLMs As Reasoners & Social Instruments", "description": "Broad grouping on evaluating large language models' reasoning, bias, persuasion, and empathy, plus their reliability as annotators, fact-checkers, and survey simulators via probing, interpretability, and interpretable benchmarks."}, "3": {"label": "Political Communication & Text Measurement", "description": "Broad grouping of political news, polarization, and civic-discourse analysis together with the methodological validation of LLM- and ASR-based content-analysis instruments over speeches, hearings, and news corpora."}, "4": {"label": "Social Media Platforms & Information Diffusion", "description": "Broad grouping on algorithmic feeds, contagion and echo chambers, online hate and protest mobilization, and cross-platform media diets studied with multimodal analysis, network diffusion models, and platform audits."}},
		clusterLayerLabels: [{"0": {"label": "Urban Mobility & Spatial Segregation", "description": "Cities as data: experienced segregation, service accessibility, displacement, and disaster resilience studied with GPS mobility traces, POI and geotagged social media, time-use surveys, and higher-order network models."}, "1": {"label": "Visual Culture & Media Stereotypes", "description": "Gender and racial stereotyping in film, fashion, fiction, and AI-generated imagery, measured at scale via computer vision, character archetype embeddings, and LLM-assisted content analysis of cultural evolution."}, "2": {"label": "Labor Markets & Career Mobility", "description": "Occupational skill compatibility, career adaptability, AI job exposure, and remote-work outcomes learned from resume-derived job-transition embeddings, time-use surveys, and administrative cohort records."}, "3": {"label": "Generative AI In Education", "description": "How students use and instructors govern generative AI in coursework, studied through LLM-annotated syllabi, admissions essays, discussion-forum posts, and learning-analytics traces with difference-in-differences and field experiments."}, "4": {"label": "LLM Behavior, Reasoning & Bias", "description": "Auditing large language models as social actors: persuasion, moral reasoning, empathy, geopolitical and social bias, fact-checking, and their validity as survey simulators or text annotators, using probing, mechanistic interpretability, and interpretable benchmarks."}, "5": {"label": "Opinion Dynamics & Collective Belief", "description": "Formal models of social influence, anticonformity, and belief-field dynamics validated with group experiments and LLM-guided belief-network elicitation to explain polarization and collective decision-making."}, "6": {"label": "Political Text, News & Media Bias", "description": "Measuring polarization, toxicity, authoritarian rhetoric, quotation gatekeeping, and crime coverage across presidential speeches, legislation, broadcast news, and social platforms with NLP, geoparsing, topic models, and audio-as-data methods."}, "7": {"label": "LLM Measurement & Text Validity", "description": "Validating computational text instruments through diachronic corpora, semantic-entropy diagnostics, ASR transcription audits, and human-LLM annotation pipelines for traits, narratives, and cross-border identity representation."}, "8": {"label": "Bias & Inequality In Science", "description": "Gender, geographic, racial, and institutional biases in citations, peer review, self-promotion, and paywall access, measured with name-based gender inference, preregistered experiments, and OpenAlex-scale bibliometrics."}, "9": {"label": "Science Of Science & Innovation", "description": "Quantifying innovation search, interdisciplinarity, talent mobility, research translation, and productivity using patents, grants, resume trajectories, and mechanistic models of academic careers and success-failure structure."}, "10": {"label": "Online Discourse & Crisis Narratives", "description": "Narrative emergence, hate-community engagement, cyberbullying, hashtag activism, and conspiracy diffusion tracked through session graphs, multimodal classification, and discourse-analysis toolkits during protests and crisis events."}, "11": {"label": "Recommendation Algorithms & Diffusion", "description": "How recommender feeds and influencer amplification shape virality, attitudes, and cross-platform media diets, modeled with hypergraph diffusion, retweet-cascade emotion analysis, and governance-adoption event-history methods."}}, {"0": {"label": "Spatial Mobility & Urban Segregation", "description": "Broad grouping of spatial computational social science on mobility, experienced segregation, accessibility, displacement, and cultural consumption using POI, geotagged, GPS, and higher-order network data."}, "1": {"label": "Science, Careers, Culture & Education", "description": "Broad grouping spanning science-of-science and innovation, academic bias and careers, labor mobility, media and gender stereotypes, and generative AI in education, largely via bibliometric, resume, and LLM-annotation methods."}, "2": {"label": "LLMs As Reasoners & Social Instruments", "description": "Broad grouping on evaluating large language models' reasoning, bias, persuasion, and empathy, plus their reliability as annotators, fact-checkers, and survey simulators via probing, interpretability, and interpretable benchmarks."}, "3": {"label": "Political Communication & Text Measurement", "description": "Broad grouping of political news, polarization, and civic-discourse analysis together with the methodological validation of LLM- and ASR-based content-analysis instruments over speeches, hearings, and news corpora."}, "4": {"label": "Social Media Platforms & Information Diffusion", "description": "Broad grouping on algorithmic feeds, contagion and echo chambers, online hate and protest mobilization, and cross-platform media diets studied with multimodal analysis, network diffusion models, and platform audits."}}],
